#!/usr/bin/env node
/**
 * avoro-lint — Avoro brand rules linter.
 *
 * Scans .ts/.tsx/.js/.jsx/.css/.scss/.md/.html files and fails on:
 *   - hardcoded hex codes (must come from @avoro/brand-tokens)
 *   - pure #fff / #000 (warm neutrals only — Paper #FAFAF7 / Ink #0E0E10)
 *   - CSS gradients (linear-gradient / radial-gradient / conic-gradient)
 *   - backdrop-filter / -webkit-backdrop-filter (no glassmorphism)
 *   - banned vocabulary (realtor, empower, revolutionize, seamless, etc.)
 *
 * Opt-out per line:  // avoro-lint-ignore     or    /* avoro-lint-ignore *​/
 *
 * Exits 0 if clean, 1 if any violations found.
 *
 * Run via:  npx avoro-lint            (after consuming app installs @avoro/brand-tokens)
 *           node scripts/avoro-lint.mjs   (from this repo)
 */

import { readdirSync, readFileSync, statSync, existsSync } from "node:fs";
import { join, relative, extname } from "node:path";

const ROOT = process.cwd();

// Don't walk into these.
const IGNORE_DIRS = new Set([
  "node_modules", ".git", ".next", ".turbo", ".vercel",
  "dist", "build", "out", "coverage", ".cache", "public",
]);

// Files where hardcoded hex codes are allowed. Each entry is a regex tested
// against the project-relative POSIX path (e.g. "src/tokens.ts", "tests/foo.test.mjs").
const ALLOW_HEX = [
  /(^|\/)tokens\.(ts|js|mjs|cjs|css)$/,           // source of truth
  /(^|\/)design-tokens\.json$/,                    // source of truth
  /(^|\/)dist\/(css-variables\.css|.+\.(mjs|cjs|d\.ts|js))$/, // built output
  /(^|\/)avoro-lint[^\/]*\.(mjs|js)$/,             // the linter itself defines the patterns
  /(^|\/)tests\/.+\.(test|spec)\.(mjs|js|ts)$/,    // contract tests assert exact values
  /(^|\/)CLAUDE\.md$/,                             // rules doc references specific hexes by name
];

// Files where banned vocabulary may appear (because they NAME what's banned).
const ALLOW_BANNED = [
  /(^|\/)CLAUDE\.md$/,                             // the rules doc lists what we don't say
  /(^|\/)voice-and-tone\.md$/,                     // long-form voice guide does the same
  /(^|\/)avoro-lint[^\/]*\.(mjs|js)$/,             // patterns + example messages live here
  /(^|\/)linter\/README\.md$/,                     // linter docs enumerate what it catches
];

function isAllowed(relPath, patterns) {
  return patterns.some((p) => p.test(relPath));
}

const EXTENSIONS = new Set([
  ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs",
  ".css", ".scss", ".sass",
  ".html", ".md", ".mdx",
]);

// ---------- Rule sets ----------

const STYLE_RULES = [
  { id: "no-linear-gradient", pattern: /linear-gradient\s*\(/g, message: "No gradients. Solid fills only." },
  { id: "no-radial-gradient", pattern: /radial-gradient\s*\(/g, message: "No gradients. Solid fills only." },
  { id: "no-conic-gradient",  pattern: /conic-gradient\s*\(/g,  message: "No gradients. Solid fills only." },
  { id: "no-backdrop-filter", pattern: /(^|[^a-zA-Z-])(-webkit-)?backdrop-filter\s*:/g, message: "No glassmorphism. Remove backdrop-filter." },
];

const PURE_BW_RULES = [
  { id: "no-pure-white-hex", pattern: /#fff(fff)?\b/gi,                              message: "No pure white. Use Paper (#FAFAF7) or var(--avoro-paper)." },
  { id: "no-pure-black-hex", pattern: /#000(000)?\b/gi,                              message: "No pure black. Use Ink (#0E0E10) or var(--avoro-ink)." },
  { id: "no-pure-white-rgb", pattern: /rgba?\(\s*255\s*,\s*255\s*,\s*255\b/g,        message: "No pure white. Use Paper (#FAFAF7)." },
  { id: "no-pure-black-rgb", pattern: /rgba?\(\s*0\s*,\s*0\s*,\s*0(?!\s*,\s*0\.)/g,  message: "No pure black. Use Ink (#0E0E10)." },
];

const HEX_RULE = {
  id: "no-hardcoded-hex",
  pattern: /#[0-9a-fA-F]{3}(?:[0-9a-fA-F]{3}(?:[0-9a-fA-F]{2})?)?\b/g,
  message: "Hardcoded hex. Import from @avoro/brand-tokens (colors.brand.*, colors.neutral.*, or var(--avoro-*)).",
};

// Banned vocabulary. High-confidence only — common English words excluded to avoid false positives.
const BANNED_WORDS = [
  { id: "banned-realtor",       pattern: /\brealtors?\b/gi,                  message: 'Banned: "realtor". Use "agents" or "teams".' },
  { id: "banned-realtor-tm",    pattern: /\bREALTOR®?\b/g,                   message: 'Banned: "REALTOR®". Use "agents" or "teams".' },
  { id: "banned-empower",       pattern: /\bempower(ing|ed|s|ment)?\b/gi,    message: 'Banned: "empower". Cut the word.' },
  { id: "banned-revolutionize", pattern: /\brevolution(ize|izing|ized|ary|aries|izes)\b/gi, message: 'Banned: "revolutionize/revolutionary".' },
  { id: "banned-seamless",      pattern: /\bseamless(ly)?\b/gi,              message: 'Banned: "seamless". Every startup uses it — meaningless.' },
  { id: "banned-ecosystem",     pattern: /\becosystem\b/gi,                  message: 'Banned: "ecosystem". Use "platform".' },
  { id: "banned-game-changer",  pattern: /\bgame[- ]changer/gi,              message: 'Banned: "game-changer".' },
  { id: "banned-world-class",   pattern: /\bworld[- ]class\b/gi,             message: 'Banned: "world-class".' },
  { id: "banned-next-gen",      pattern: /\bnext[- ]generation\b/gi,         message: 'Banned: "next-generation".' },
  { id: "banned-proud",         pattern: /\bproud to announce\b/gi,          message: 'Banned: "proud to announce". Just announce it.' },
  { id: "banned-dream-home",    pattern: /\bdream home\b/gi,                 message: 'Banned: "dream home".' },
  { id: "banned-year-language", pattern: /\bYear\s+[1-5]\b/g,                message: 'Use "Phase 1/2/3", not calendar-year language.' },
  // Retired v1.0 positioning — hard-banned 2026-08-06 (Seth, co-founder/CEO).
  { id: "banned-splits",        pattern: /(?<![.\w])splits?\b(?!\s*\()/gi,   message: 'HARD BAN: "splits". Avoro NEVER pays splits or moves commission money. Use "expense ratio", "commission economics", or "production". (Code method .split() is exempt.)' },
  { id: "banned-payouts",       pattern: /\bpay-?outs?\b/gi,                 message: 'HARD BAN: "payouts". Avoro doesn\'t do payouts. Name the actual work.' },
  { id: "banned-rails",         pattern: /\brails\b/gi,                      message: 'Banned: "rails". Meaningless and unclear. Use "operating intelligence" or "platform".' },
  { id: "banned-os-identity",   pattern: /\b(the\s+)?operating system for (modern )?real estate\b|\bwe (are|build) the operating system\b|\bAvoro('s)? operating system\b/gi, message: 'Banned: "operating system" as what Avoro is. Foil use only ("Seventeen logins is not an operating system."). Avoro is operating intelligence.' },
];

// ---------- Walker ----------

function walk(dir) {
  const out = [];
  let entries;
  try { entries = readdirSync(dir); } catch { return out; }
  for (const name of entries) {
    if (IGNORE_DIRS.has(name)) continue;
    if (name.startsWith(".") && name !== ".github") continue;
    const full = join(dir, name);
    let stat;
    try { stat = statSync(full); } catch { continue; }
    if (stat.isDirectory()) out.push(...walk(full));
    else if (EXTENSIONS.has(extname(name))) out.push(full);
  }
  return out;
}

// ---------- Checker ----------

function check(filePath, rules) {
  const rel = relative(ROOT, filePath).split("\\").join("/");
  let text;
  try { text = readFileSync(filePath, "utf8"); } catch { return []; }
  const lines = text.split("\n");
  const violations = [];

  for (const { id, pattern, message } of rules) {
    pattern.lastIndex = 0;
    let m;
    while ((m = pattern.exec(text)) !== null) {
      const before = text.slice(0, m.index);
      const line = before.split("\n").length;
      const col = m.index - before.lastIndexOf("\n");

      const lineText = lines[line - 1] || "";
      if (lineText.includes("avoro-lint-ignore")) continue;

      violations.push({ file: rel, line, col, match: m[0], id, message });
      if (!pattern.global) break;
    }
  }
  return violations;
}

// ---------- Main ----------

const files = walk(ROOT);
const violations = [];

for (const file of files) {
  const rel = relative(ROOT, file).split("\\").join("/");
  const ext = extname(file);
  const isMarkdown = ext === ".md" || ext === ".mdx";
  const isStyleish = ext === ".css" || ext === ".scss" || ext === ".sass" ||
                     ext === ".tsx" || ext === ".jsx" || ext === ".html";

  // Banned vocabulary applies everywhere except files on the banned-words allow-list.
  if (!isAllowed(rel, ALLOW_BANNED)) {
    violations.push(...check(file, BANNED_WORDS));
  }

  // Style + pure black/white checks: only on files that render styles.
  if (isStyleish) {
    violations.push(...check(file, STYLE_RULES));
    violations.push(...check(file, PURE_BW_RULES));
  }

  // Hex-code rule: skip files on the hex allow-list, skip pure docs.
  if (!isAllowed(rel, ALLOW_HEX) && !isMarkdown) {
    violations.push(...check(file, [HEX_RULE]));
  }
}

if (violations.length === 0) {
  console.log(`\u2713 avoro-lint: 0 violations across ${files.length} files.`);
  process.exit(0);
}

// Group by file for readable output.
const byFile = new Map();
for (const v of violations) {
  if (!byFile.has(v.file)) byFile.set(v.file, []);
  byFile.get(v.file).push(v);
}

console.error(`\u2717 avoro-lint: ${violations.length} violation(s) in ${byFile.size} file(s):\n`);
for (const [file, vs] of byFile) {
  console.error(`  ${file}`);
  for (const v of vs) {
    console.error(`    ${v.line}:${v.col}  [${v.id}]  "${v.match}"`);
    console.error(`      → ${v.message}`);
  }
  console.error("");
}
console.error(`Add  // avoro-lint-ignore  to a line to suppress (use sparingly).`);
process.exit(1);
